<?php require_admin();$stats=q('SELECT COUNT(*) c,COALESCE(SUM(cantidad_almacen),0) stock FROM productos')->fetch();$orders=q('SELECT COUNT(*) n,COALESCE(SUM(total),0) monto FROM compras')->fetch();$products=q('SELECT * FROM productos ORDER BY id DESC')->fetchAll();?><div class="container py-5"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-4"><div><div class="kicker mb-3">PANEL ADMINISTRADOR</div><h1 style="font-size:3.3rem">Inventario</h1></div><a href="index.php?page=admin_producto" class="btn btn-brand">+ Nuevo producto</a></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="surface p-4"><div class="small-muted">Productos registrados</div><h2><?= (int)$stats['c'] ?></h2></div></div><div class="col-md-4"><div class="surface p-4"><div class="small-muted">Unidades en almacén</div><h2><?= (int)$stats['stock'] ?></h2></div></div><div class="col-md-4"><div class="surface p-4"><div class="small-muted">Compras simuladas</div><h2><?= (int)$orders['n'] ?></h2><a href="index.php?page=admin_pedidos">Ver historial →</a></div></div></div><div class="surface p-3 p-lg-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td>#<?=(int)$p['id']?></td><td><img class="admin-thumb me-2" src="<?=h(product_image($p))?>" alt=""><span class="fw-semibold"><?=h($p['nombre'])?></span></td><td><?=h($p['categoria'])?></td><td><?=money($p['precio'])?></td><td><span class="badge <?=$p['cantidad_almacen']<10?'text-bg-warning':'text-bg-success'?>"><?=(int)$p['cantidad_almacen']?></span></td><td><?= $p['activo']?'Activo':'Oculto' ?></td><td><a href="index.php?page=admin_producto&id=<?=(int)$p['id']?>" class="btn btn-sm btn-outline-brand">Editar</a></td></tr><?php endforeach ?></tbody></table></div></div><div class="surface p-4 mt-4"><h3>Inventario de materias primas</h3><p class="small-muted">Las fórmulas personalizadas descuentan gramos de ingredientes de esta tabla.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Ingrediente</th><th>Categoría</th><th>Disponible (g)</th></tr></thead><tbody><?php foreach(q('SELECT nombre,categoria,stock_gramos FROM ingredientes ORDER BY categoria,id')->fetchAll() as $i):?><tr><td><?=h($i['nombre'])?></td><td><?=h($i['categoria'])?></td><td><?=number_format((float)$i['stock_gramos'],2)?></td></tr><?php endforeach ?></tbody></table></div></div></div>
